llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "DX-9065a, a non-peptidic small molecule combining strongly basic amidino groups with a carboxylic acid, has a human oral bioavailability of only 2–3%, attributed to the strong basic amidino groups; the query shares the same benzamidine-plus-carboxylate ionizable motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Pentamidine, a bis-benzamidine drug, has poor oral bioavailability in humans; the query contains a benzamidine group and is similarly highly ionized, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "A human absolute bioavailability study of a molecule containing an amidine and two carboxylic acids found it 'not high enough for oral use,' directly supporting low F for the query's amidine/carboxylate scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Peramivir, a guanidine- and carboxylate-containing antiviral, has ≤3% oral bioavailability in humans, reinforcing that strongly basic/carboxylate zwitterions of this size are poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "L-arginine, a small guanidino amino acid, can reach ~68% oral bioavailability in humans via dedicated amino-acid transporters; this high-F result is contradictory in direction but weakly transferable to the much larger, non-substrate-like peptidomimetic query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Atenolol, a smaller monobasic polar drug, has ~50% absolute oral bioavailability, but its single ionizable center, lower TPSA, and smaller size limit transfer to the query's fully ionized amidine/carboxylate scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low oral bioavailability (<20%). The query's strongly basic benzamidine, free carboxylate, multiple amide/H-bond donors, and very low logD align with human low-F analogues (DX-9065a 2–3%, pentamidine poor, peramivir ≤3%, amidine/carboxylate compound not orally viable). High-F small molecules like L-arginine and atenolol are not transferable because of size, transporter specificity, and lower polar/ionization burden.",
  "evidence_gaps": [
    "No direct human or animal pharmacokinetic data for the query molecule.",
    "No evidence addressing the fed-state condition specifically.",
    "No data on whether the query is a substrate for intestinal transporters that could improve absorption.",
    "Perindoprilat 30% F is confounded by prodrug administration and cirrhosis, so it is not a reliable high-F anchor."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

